UPDATE edicoes edicao SET url_capa=capas.url_capa FROM capas WHERE EXISTS (SELECT 1 FROM series serie JOIN editoras editora ON editora.id=serie.editora_id WHERE serie.id=edicao.serie_id AND hqhub_normalizar_titulo_serie(editora.nome) LIKE 'panini%' AND coalesce(serie.volume,1)=2 AND hqhub_normalizar_titulo_serie(serie.titulo) IN (hqhub_normalizar_titulo_serie('Liga da Justiça'),hqhub_normalizar_titulo_serie('Liga da Justiça 2ª Série'),hqhub_normalizar_titulo_serie('Liga da Justiça - 2ª Série'))) AND hqhub_normalizar_identidade(edicao.numero)=hqhub_normalizar_identidade(capas.numero::text);

